/*
 * Alle teksten van de app in het Nederlands (besluit 185). Eén sleutel per
 * tekst; taal.js kiest de taal. `{naam}` vult zich met wat de code meegeeft,
 * `**zo**` wordt vet waar de code taal.html gebruikt, en een meervoud staat
 * als `{ one, other }` (en eventueel `zero`) met `n` erbij.
 *
 * Stap 8: het menu, Thuis en Hoe voelt het. De rest volgt pagina voor pagina
 * (stap 9); een test houdt dit bestand en teksten.en.js gelijk.
 */
