  'rond.dakBoven.tekst': 'Elk dakvlak met panelen heeft een letter. Tik een vlak aan om het te openen, of tik een leeg dak aan om er een vlak bij te zetten.',
  'rond.dakLijst.kop': 'Elk vlak apart',
  'rond.dakLijst.tekst': 'Per vlak de richting, de helling en hoeveel panelen. Groen is gemeten, blauw stelde je zelf in, oranje is nog geschat.',
