  'rond.dakHuis.kop': 'Je huis, met de panelen erop',
  'rond.dakHuis.tekst': 'Zoals op Thuis: elk vlak met zijn letter op zijn eigen dak. Zo zie je meteen of het klopt met je echte huis.',
  'daken.uitleg': 'Zo werkt Daken en panelen',
  'rond.dakErbij.kop': 'Een vlak erbij',
  'rond.dakErbij.tekst': 'Panelen op de garage, een uitbouw, de carport of in de tuin? Zet ze erbij, elk met zijn eigen richting.',
  'rond.dakWatkan.kop': 'Wat kan bij jouw huis',
  'rond.dakWatkan.tekst': 'Zie of je huis op de plattegrond of de 3D-kaart van Nederland staat, en kies waar het uit getekend wordt. Of teken het zelf: tik een gebouw aan en sleep het op zijn plek.',
  'rond.dakMeters.kop': 'Omvormers en meters',
  'rond.dakMeters.tekst': 'Welke omvormer welke vlakken meet. Meet er één meer vlakken, dan verdeelt SunArc wat hij meet naar wat elk vlak bij heldere lucht levert.',
