  'rond.overslaan': 'Overslaan',
  'rond.volgende': 'Volgende',
  'rond.huis.kop': 'Dit is je huis',
  'rond.huis.tekst': 'Alles wat er nu gebeurt. De kleur van een kamer zegt wat hij doet: blauw koelt, oranje verwarmt, groen is goed.',
  'rond.kamerTik.kop': 'Tik op een kamer',
  'rond.kamerTik.tekst': 'Dan zie je hem van dichtbij. Dat doen we nu even voor je.',
  'rond.kamer.kop': 'De kamer van dichtbij',
  'rond.kamer.tekst': 'De temperatuur, wat er draait, en de lampen, scènes en screens om meteen te bedienen.',
  'rond.gevoel.kop': 'Hoe voelt het?',
  'rond.gevoel.tekst': 'Tik wat je voelt. Het huis leert ervan wat jij prettig vindt, en stelt voor wat het anders kan.',
  'rond.vandaag.kop': 'Wat er vandaag gebeurt',
  'rond.vandaag.tekst': 'Uur voor uur: de zon, de kamers en wat het huis deed, en waarom.',
  'rond.tedoen.kop': 'Wat er te doen is',
  'rond.tedoen.tekst': 'Je herinneringen, het afval, de agenda en de boodschappen bij elkaar. Zeg "Hé huis, herinner me…" of typ het hier.',
  'rond.gisteren.kop': 'Gisteren en morgen',
  'rond.gisteren.tekst': 'Bij Gisteren zie je of de verwachting klopte; bij Morgen wanneer de zon komt.',
  'rond.apparaten.kop': 'Wat elk apparaat nu doet',
  'rond.apparaten.tekst': 'Per apparaat wat het doet en vraagt, en wat het vandaag op eigen zon deed.',
  'rond.opbrengst.kop': 'Wat je panelen opleverden',
  'rond.opbrengst.tekst': 'In kWh en in euro, per dag, week, maand en jaar. En waar je stroom heen ging.',
  'rond.assistent.kop': 'Vraag het je huis',
  'rond.assistent.tekst': 'Tik op de bol en het huis praat. Vraag wat het doet, waarom, of wat morgen brengt.',
  'rond.bel.kop': 'De bel',
  'rond.bel.tekst': 'Hier staat wat nieuw is, en wat aandacht vraagt, zoals een batterij die bijna leeg is.',
  'rond.naarHA.kop': 'Volledig scherm',
  'rond.naarHA.tekst': 'In de app van Home Assistant staat SunArc over het hele scherm. Met deze knop ga je naar Home Assistant, en met dezelfde knop weer terug. Liever met de balken van Home Assistant? Zet het uit bij Instellingen › Functies › Dit scherm.',
  'rond.tandwiel.kop': 'Het tandwiel',
  'rond.tandwiel.tekst': 'Comfort, de regeling, energie en je huis. Alles wat je bij Inrichten koos, staat hier.',
  'rond.huisKan.kop': 'Hoe ver het huis is',
  'rond.huisKan.tekst': 'Per functie of hij werkt, meekijkt of nog leert, en wat er nog bij kan.',
  'rond.klaar.kop': 'Klaar',
  'rond.klaar.tekst': 'Het huis kijkt mee. Na 30 winterdagen weet het genoeg om zelf te regelen; je ziet het groeien bij Wat je huis kan. Terugkijken kan bij het vraagteken op Thuis.',

